#define main original_main
#include "search.cpp"
#undef main
struct PS{G g;int n,k;array<int,32>c{};vector<array<int,3>>nb;PS(G const&h,int u,int v,int k):g(h),n(h.n),k(k){g.n+=2;g.del(u,v);g.add(u,n);g.add(v,n+1);c.fill(-1);for(int i=0;i<n;i++){array<int,3>t;U m=g.a[i];for(int&x:t){x=lo(m);m&=m-1;}nb.push_back(t);}}
 bool local(int v){if(v>=n)return true;U m=0;int free=0;for(int u:nb[v])if(c[u]<0)free++;else{if(c[u]==c[v])return false;m|=1u<<c[u];}return pc(m)<=2&&pc(m)+free>=2;}
 bool dfs(int left,int used){if(!left)return true;int v=-1,best=-1;for(int i=0;i<n;i++)if(c[i]<0){int s=0;for(int j:nb[i]){s+=4*(c[j]>=0);if(j<n)for(int h:nb[j])s+=c[h]>=0;}if(s>best)best=s,v=i;}for(int x=0;x<min(k,used+1);x++){c[v]=x;bool ok=local(v);for(int u:nb[v])ok&=local(u);if(ok&&dfs(left-1,max(used,x+1)))return true;c[v]=-1;}return false;}
 bool solve(int u,int v,array<int,4>p){c.fill(-1);c[u]=p[0];c[v]=p[1];c[n]=p[2];c[n+1]=p[3];for(int i=0;i<n;i++)if(!local(i))return false;return dfs(n-2,*max_element(p.begin(),p.end())+1);}};
struct PT{G g;int n;vector<array<int,3>>nb;PT(G const&h,int u,int v):g(h),n(h.n){g.n+=2;g.del(u,v);g.add(u,n);g.add(v,n+1);for(int i=0;i<n;i++){array<int,3>t;U m=g.a[i];for(int&x:t){x=lo(m);m&=m-1;}nb.push_back(t);}}bool valid(UF const&f,vector<pair<int,int>>const&neq){for(auto[a,b]:neq)if(f.r(a)==f.r(b))return false;return true;}
 bool dfs(UF f,vector<pair<int,int>>neq,U rem){if(!rem)return true;int v=-1;U opt=0;for(U m=rem;m;m&=m-1){int i=lo(m);U o=0;for(int j=0;j<3;j++){int a=nb[i][(j+1)%3],b=nb[i][(j+2)%3],c=nb[i][j];UF h=f;h.join(a,b);if(h.r(a)!=h.r(c)&&valid(h,neq))o|=1u<<j;}if(!o)return false;if(v<0||pc(o)<pc(opt)){v=i;opt=o;if(pc(o)==1)break;}}for(U m=opt;m;m&=m-1){int j=lo(m),a=nb[v][(j+1)%3],b=nb[v][(j+2)%3],c=nb[v][j];UF h=f;h.join(a,b);auto nn=neq;nn.emplace_back(a,c);if(dfs(h,nn,rem^(1u<<v)))return true;}return false;}
 bool solve(int u,int v,array<int,4>p){UF f;vector<pair<int,int>>neq=g.edges();array<int,4>w{u,v,n,n+1};for(int i=0;i<4;i++)for(int j=i+1;j<4;j++){if(p[i]==p[j])f.join(w[i],w[j]);else neq.emplace_back(w[i],w[j]);}return valid(f,neq)&&dfs(f,neq,(1u<<n)-1);}};
int main(int argc,char**argv){int maxn=argc>1?atoi(argv[1]):12;vector<array<int,4>>patterns;for(int a=0;a<=1;a++)for(int b=0;b<=max(0,a)+1;b++)for(int c=0;c<=max(a,b)+1;c++){array<int,4>p{0,a,b,c};if(p[0]!=p[2]&&p[1]!=p[3])patterns.push_back(p);}auto norm=[](array<int,4>p){map<int,int>m;for(int&x:p){if(!m.count(x)){int j=m.size();m[x]=j;}x=m[x];}return p;};vector<int>rev;for(auto p:patterns){auto q=norm({p[2],p[3],p[0],p[1]});rev.push_back(find(patterns.begin(),patterns.end(),q)-patterns.begin());for(int x:p)cout<<x;cout<<" ";}cout<<endl;map<pair<int,int>,string>types;int count=0;for(int n=6;n<=maxn;n+=2){ifstream file("graphs_"+to_string(n)+".g6");string s;while(file>>s){G g=parse(s);for(auto[u,v]:g.edges()){PS f(g,u,v,4);PT h(g,u,v);int four=0,any=0;for(int i=0;i<(int)patterns.size();i++){if(f.solve(u,v,patterns[i]))four|=1<<i,any|=1<<i;else if(h.solve(u,v,patterns[i]))any|=1<<i;}count++;string tag=s+" "+to_string(u)+" "+to_string(v);types.try_emplace({four,any},tag);if(four!=any)cout<<"GAP "<<tag<<" "<<four<<" "<<any<<endl;}}cerr<<n<<" checked "<<count<<" types "<<types.size()<<endl;}
for(auto [p,s]:types)cout<<"TYPE "<<p.first<<" "<<p.second<<" "<<s<<endl;for(auto[p,s]:types)for(auto[q,t]:types){int a=0,b=0;for(int i=0;i<(int)patterns.size();i++){if((p.first>>i&1)&&(q.first>>rev[i]&1))a=1;if((p.second>>i&1)&&(q.second>>rev[i]&1))b=1;}if(!a&&b)cout<<"COUNTEREXAMPLE "<<s<<" / "<<t<<endl;}}
